def plans_to_packages(apps, schema_editor):
    """Old plans (a period with classes per week and a table price) become packages: classes = per week x 4 x months
    (1 per week when it was not set), deadline = 30 days per month, the table price becomes the total."""
    Package = apps.get_model("core", "Package")
    for package in Package.objects.all():
        weekly = package.sessions_per_week or 1
        package.sessions = max(weekly * 4 * package.months, 1)
        package.valid_days = package.months * 30
        package.pricing_mode = "total"
        package.price_total = package.price
        if package.price is not None:
            package.price_per_session = (package.price / package.sessions).quantize(Decimal("0.01"))
        package.save()


